epochs-bare:
{
  "model": "textonly",
  "stream": true,
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "ask_user",
        "description": "Ask the user one or more multiple-choice questions and wait for the answers. Use only when options have materially different tradeoffs the user must weigh; resolve everything else from context. Each question: `id`, `question`, 2-5 short `options` ({label, description?}), optional `recommended` index. The user may pick an option, type a freeform answer, or skip a question; dismissing the whole set ends your turn. Returns one line per question and a `{id: answer | null}` map.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "AskArgs",
          "description": "Arguments of `ask_user`.",
          "type": "object",
          "properties": {
            "questions": {
              "description": "One or more questions, shown together.",
              "type": "array",
              "items": {
                "$ref": "#/$defs/Question"
              }
            }
          },
          "required": [
            "questions"
          ],
          "$defs": {
            "Question": {
              "description": "One question. The user picks an option, types a freeform answer, or skips.",
              "type": "object",
              "properties": {
                "id": {
                  "description": "Short stable key; the answer is reported under it.",
                  "type": "string"
                },
                "question": {
                  "description": "The question text.",
                  "type": "string"
                },
                "options": {
                  "description": "2–5 distinct options; may be empty for a freeform-only question.",
                  "type": "array",
                  "items": {
                    "$ref": "#/$defs/Choice"
                  },
                  "default": []
                },
                "recommended": {
                  "description": "Index into `options` you recommend; shown to the user as such.",
                  "type": [
                    "integer",
                    "null"
                  ],
                  "format": "uint",
                  "minimum": 0
                }
              },
              "required": [
                "id",
                "question"
              ]
            },
            "Choice": {
              "description": "One selectable answer.",
              "type": "object",
              "properties": {
                "label": {
                  "description": "Short label (a few words).",
                  "type": "string"
                },
                "description": {
                  "description": "Optional tradeoff or explanation shown under the label.",
                  "type": [
                    "string",
                    "null"
                  ]
                }
              },
              "required": [
                "label"
              ]
            }
          }
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "cancel_job",
        "description": "Kill a running background job by id. This reply is the whole acknowledgement: no <job_result> follows a job you killed.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "CancelJobArgs",
          "description": "Arguments for [`CancelJobTool`].",
          "type": "object",
          "properties": {
            "id": {
              "description": "Job id from the `shell` stub or `jobs`, e.g. `j3`.",
              "type": "string"
            }
          },
          "required": [
            "id"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "cancel_reminder",
        "description": "Cancel a pending reminder by id; no <reminder> will follow for it.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "CancelReminderArgs",
          "description": "Arguments for [`CancelReminderTool`].",
          "type": "object",
          "properties": {
            "id": {
              "description": "Reminder id from `remind_me_in`, e.g. `r3`.",
              "type": "string"
            }
          },
          "required": [
            "id"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "clip",
        "description": "Store a block of text under a name without retyping it, to paste later with copy_text(src=\"clip:<name>\"): `src` is `path#L<n>-L<m>@<id>` (lines from the read_file header id) or `path#Symbol`. The text is taken as it is now; a clip of the same name is replaced. Clips live in memory for this session (1 MiB each, 64 clips, 16 MiB in all) and are lost when the engine restarts. Cut-and-paste-later is clip, then edit(range=…, new=\"\") to delete.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "ClipArgs",
          "description": "Arguments for [`ClipTool`].",
          "type": "object",
          "properties": {
            "name": {
              "description": "Clip name: 1-64 of `A-Z a-z 0-9 _ . -`; an existing clip of that\nname is replaced.",
              "type": "string"
            },
            "src": {
              "description": "`path#L<n>-L<m>@<id>` or `path#Symbol`.",
              "type": "string"
            }
          },
          "required": [
            "name",
            "src"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "copy_text",
        "description": "Copy a block of text without retyping it: as move_text, but the source stays, and `src` may also be `clip:<name>` (a block stored earlier with clip). Targets: `before`/`after` (`path#L<n>@<id>` or `path#Symbol`) or `at` (`path#start`/`path#end`, creating a missing file). `indent`: \"match\" (default), \"keep\", \"+N\"/\"-N\" levels. Returns a receipt with the target's new snapshot id and the lines either side of the paste.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "CopyTextArgs",
          "description": "Arguments for [`CopyText`].",
          "type": "object",
          "properties": {
            "src": {
              "description": "As `move_text.src`, or `clip:<name>` for a stored clip.",
              "type": "string"
            },
            "before": {
              "description": "Insert above this line or symbol: `path#L<n>@<id>` or `path#Symbol`.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "after": {
              "description": "Insert below this line or symbol.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "at": {
              "description": "`path#start` or `path#end`; creates a missing file.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "indent": {
              "description": "`\"match\"` (default), `\"keep\"`, `\"+N\"`/`\"-N\"` levels.",
              "type": "string",
              "default": "match"
            }
          },
          "required": [
            "src"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "edit",
        "description": "Replace `old` with `new` in a text file, or apply several `edits` in order (each sees the previous result; any failure writes nothing). Matching is exact first, then tolerant of trailing whitespace and a uniform indentation offset, then of any whitespace differences on whole lines, and as a last resort `cat -n` line-number prefixes (`N<tab>`, as read_file prints them) are stripped from `old` (and from `new` when every line has them); a match at more than one place is an error unless `all` is true, and a miss reports the closest region as a diff with its line numbers. Returns a unified diff of what changed, then `<path> @<id>`, the file's new snapshot id. Instead of quoting `old`, `range` names whole lines without retyping them: `L40-L52@<id>` (the id from the read_file header or a receipt; the numbers follow your own later edits, and a change to those very lines is refused with their current text) or a symbol name (`Reader.load`, with its doc comments and attributes); `new` replaces those lines, `new=\"\"` deletes them; `edits` entries may all use `range` instead (applied together, no overlaps); a range edit answers with a one-line receipt. A `new` carrying a read_file header or truncation marker is refused; paths are relative to the working directory, `~` is not expanded.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "EditArgs",
          "description": "Arguments for [`Edit`].",
          "type": "object",
          "properties": {
            "path": {
              "description": "File path, absolute or relative to the session's working directory (no `~`).",
              "type": "string"
            },
            "old": {
              "description": "Text to replace (single-edit form). Mutually exclusive with `edits`\nand `range`.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "range": {
              "description": "Whole lines to replace (single-edit form), instead of `old`:\n`L<n>@<id>`, `L<n>-L<m>@<id>` (the id from the read_file header or a\nreceipt; numbers follow your own later edits) or a symbol name\n(`Reader.load`, with its doc comments and attributes). `new` replaces\nthe lines, line breaks included; `new=\"\"` deletes them.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "new": {
              "description": "Replacement text (single-edit form).",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "all": {
              "description": "Replace every occurrence instead of requiring exactly one (single-edit\nform, or the default for `edits` entries that omit it). `old` only.",
              "type": "boolean",
              "default": false
            },
            "edits": {
              "description": "Several replacements to the same file, all-or-nothing: `old` entries\napply in order, each seeing the previous one's result; `range`\nentries name lines of the file as read and apply together.",
              "type": [
                "array",
                "null"
              ],
              "items": {
                "$ref": "#/$defs/EditOp"
              },
              "default": null
            }
          },
          "required": [
            "path"
          ],
          "$defs": {
            "EditOp": {
              "description": "One replacement in [`EditArgs::edits`]: `old` or `range`, the same kind\nin every entry of one list.",
              "type": "object",
              "properties": {
                "old": {
                  "description": "Text to replace.",
                  "type": [
                    "string",
                    "null"
                  ],
                  "default": null
                },
                "range": {
                  "description": "Whole lines to replace instead of `old`: `L<n>@<id>`, `L<n>-L<m>@<id>`\n(the id from the read_file header or a receipt) or a symbol name.",
                  "type": [
                    "string",
                    "null"
                  ],
                  "default": null
                },
                "new": {
                  "description": "Replacement text.",
                  "type": "string"
                },
                "all": {
                  "description": "Replace every occurrence; default: the top-level `all`. `old` only.",
                  "type": [
                    "boolean",
                    "null"
                  ],
                  "default": null
                }
              },
              "required": [
                "new"
              ]
            }
          }
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "glob",
        "description": "Find files by glob pattern: `*` matches within one path segment, `**` crosses directories; a pattern without `/` matches file names anywhere under `path` (e.g. `*.rs`), one with `/` matches paths relative to `path` (e.g. `src/**/*.rs`). Respects .gitignore and skips hidden files unless `hidden` is true; directories and symlinks are not listed. Returns paths relative to `path` (default: cwd), newest-modified first, up to `limit` (default 500). When an ancestor .gitignore would hide `path` itself, the walk ignores ancestor rules and says so in a header line.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "GlobArgs",
          "description": "Arguments for [`Glob`].",
          "type": "object",
          "properties": {
            "pattern": {
              "description": "Gitignore-style glob. `*` does not cross `/`, `**` does. Without a\n`/` it matches file names anywhere under `path` (`*.rs`); with one it\nmatches paths relative to `path` (`src/**/*.rs`).",
              "type": "string"
            },
            "path": {
              "description": "Directory to search; default: the working directory.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "limit": {
              "description": "Maximum number of paths to return; default 500.",
              "type": [
                "integer",
                "null"
              ],
              "format": "uint32",
              "minimum": 0,
              "default": null
            },
            "hidden": {
              "description": "Include dot-files and dot-directories.",
              "type": "boolean",
              "default": false
            }
          },
          "required": [
            "pattern"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "grep",
        "description": "Search file contents with a regex. Respects .gitignore, skips hidden and binary files. Returns `path:line: text` per match, sorted by path, up to `limit` (default 200). `path` is a file or directory (default: cwd); `glob` filters files, e.g. `*.rs`. When an ancestor .gitignore would hide `path` itself, the walk ignores ancestor rules and says so in a header line.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "GrepArgs",
          "description": "Arguments for [`Grep`].",
          "type": "object",
          "properties": {
            "pattern": {
              "description": "Regex to search for (Rust regex syntax).",
              "type": "string"
            },
            "path": {
              "description": "File or directory to search; default: the working directory.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "glob": {
              "description": "Only search files matching this glob, e.g. `*.rs`.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "limit": {
              "description": "Maximum number of matches to return; default 200.",
              "type": [
                "integer",
                "null"
              ],
              "format": "uint32",
              "minimum": 0,
              "default": null
            }
          },
          "required": [
            "pattern"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "indent",
        "description": "Fix a block's indentation in one call: `range` is `L<n>-L<m>@<id>` (lines from the read_file header id) or a symbol name; `by` shifts it by N levels (negative outdents, at most 64), `match=\"L<n>@<id>\"` gives it that line's indentation (plus `by` levels). The whole block moves together, keeping its inner relative indentation; the unit comes from .editorconfig or is detected from the file; blank lines become empty; where codeindex has a parser (rust, typescript, javascript, python, go), lines inside multi-line strings are left untouched. A shift that would cut into text, or indent past 1024 columns, is refused. Returns a one-line receipt with the file's new snapshot id.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "IndentArgs",
          "description": "Arguments for [`Indent`].",
          "type": "object",
          "properties": {
            "path": {
              "description": "File path, absolute or relative to the session's working directory (no `~`).",
              "type": "string"
            },
            "range": {
              "description": "The block: `L<n>-L<m>@<id>` (lines from the read_file header id) or\na symbol name (`Reader.load`).",
              "type": "string"
            },
            "by": {
              "description": "Levels to shift by (negative: outdent), in the file's own unit.",
              "type": [
                "integer",
                "null"
              ],
              "format": "int64",
              "default": null
            },
            "match": {
              "description": "A line `L<n>@<id>` in the same file whose indentation the block's\nbase takes (then `by` levels are added).",
              "type": [
                "string",
                "null"
              ],
              "default": null
            }
          },
          "required": [
            "path",
            "range"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "jobs",
        "description": "List this session's background jobs: id, state, seconds, command, last output line.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "JobsArgs",
          "description": "Arguments for [`JobsTool`]: none.",
          "type": "object"
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "list_dir",
        "description": "List a directory: one entry per line, sorted, directories end with `/`. Paths are relative to the working directory; `~` is not expanded.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "ListDirArgs",
          "description": "Arguments for [`ListDir`].",
          "type": "object",
          "properties": {
            "path": {
              "description": "Directory path, absolute or relative to the session's working directory (no `~`).",
              "type": "string"
            }
          },
          "required": [
            "path"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "move_text",
        "description": "Move a block of text without retyping it: `src` names lines you have read (`path#L40-L52@<id>`, the id from the read_file header or an earlier receipt; the line ref follows the file's later changes through that snapshot id, and is refused only if those very lines changed) or a symbol (`path#Reader.load`, widened over its doc comments, attributes and decorators). Exactly one target: `before`/`after` (`path#L<n>@<id>` or `path#Symbol`) or `at` (`path#start`/`path#end`, creating a missing file). Same file or two files, all-or-nothing. `indent=\"match\"` (default) shifts the block to fit the target, `\"keep\"` pastes it as is, `\"+N\"`/`\"-N\"` shifts by levels (at most 64); where codeindex has a parser (rust, typescript, javascript, python, go), lines inside multi-line strings are not re-indented. Returns a one-line receipt with each file's new snapshot id and the lines either side of the paste; a refusal shows the named lines as they are now.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "MoveTextArgs",
          "description": "Arguments for [`MoveText`].",
          "type": "object",
          "properties": {
            "src": {
              "description": "Source: `path#L<n>-L<m>@<id>` (lines from the read_file header id or\na receipt) or `path#Symbol` (`splice`, `Reader.load`; widened over\ndoc comments, attributes and decorators).",
              "type": "string"
            },
            "before": {
              "description": "Insert above this line or symbol: `path#L<n>@<id>` or `path#Symbol`.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "after": {
              "description": "Insert below this line or symbol.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "at": {
              "description": "`path#start` or `path#end`; creates a missing file.",
              "type": [
                "string",
                "null"
              ],
              "default": null
            },
            "indent": {
              "description": "`\"match\"` (default: fit the target's indentation), `\"keep\"`, or\n`\"+N\"`/`\"-N\"` levels from the source's own depth.",
              "type": "string",
              "default": "match"
            }
          },
          "required": [
            "src"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "read_file",
        "description": "Read a text file, an image (returned as a picture you can see) or a document (PDF, Office, ODF, RTF, EPUB) as Markdown. Paths are relative to the working directory, `~` is not expanded. An image (PNG, JPEG, GIF or WebP, detected from its bytes) comes back as a picture you can look at, with the one-line header `[read_file <path>: image/png W×H, N KB]` (`; scaled to W×H` when it was downscaled to fit); `offset`/`limit`/`tail`/`ranges`/`outline` are refused for an image. A text-only model gets a description from the vision fallback model instead, or a note that nobody has looked at it. A document is rendered from PDF / Word / PowerPoint / Excel / ODF / RTF / EPUB. For text, line 1 is always a header `[read_file <path>: N lines, B bytes, @<id>; showing lines a–b]`, then each line as `N<tab>text` (`cat -n`) — strip the `N<tab>` prefix before reusing text in `edit`/`write_file`, or pass `numbers=false` for raw text. `@<id>` names this read's snapshot: line refs take it (`path#L40-L52@<id>` in move_text, copy_text, clip; `L40-L52@<id>` in edit's `range` and indent), and they keep pointing at the same lines after your own later edits elsewhere in the file (documents and files over 4 MiB get no id). By default the first 2000 lines are shown and a `[read_file: N more lines …]` footer names the rest; select with `offset`/`limit` (1-based line window), `tail=N` (last N lines), `ranges=[[a,b],…]` (several windows, each under an `@@ lines a–b @@` line), or `outline=true` for the code_outline symbol view of an indexed source file. Lines over 2000 chars are cut with ` …[+K chars]` and output is hard-capped at 64 KiB; both are noted in the header. Never write a read result back as file content: the header, numbers and cut markers are not the file's text.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "ReadFileArgs",
          "description": "Arguments for [`ReadFile`].",
          "type": "object",
          "properties": {
            "path": {
              "description": "File path, absolute or relative to the session's working directory (no `~`).",
              "type": "string"
            },
            "offset": {
              "description": "1-based first line to return.",
              "type": [
                "integer",
                "null"
              ],
              "format": "uint",
              "minimum": 0,
              "default": null
            },
            "limit": {
              "description": "Maximum number of lines to return.",
              "type": [
                "integer",
                "null"
              ],
              "format": "uint",
              "minimum": 0,
              "default": null
            },
            "tail": {
              "description": "Return the last N lines instead; not combinable with `offset`/`limit`.",
              "type": [
                "integer",
                "null"
              ],
              "format": "uint",
              "minimum": 0,
              "default": null
            },
            "ranges": {
              "description": "1-based inclusive `[start, end]` line windows, shown in the order\ngiven, each under an `@@ lines a–b @@` line; at most `limit` lines in\ntotal (default 2000). Not combinable with `offset`/`tail`.",
              "type": [
                "array",
                "null"
              ],
              "items": {
                "type": "array",
                "items": {
                  "type": "integer",
                  "format": "uint",
                  "minimum": 0
                },
                "minItems": 2,
                "maxItems": 2
              },
              "default": null
            },
            "numbers": {
              "description": "Prefix each line with its right-aligned line number and a tab\n(`cat -n`); default true. `false` returns the raw text.",
              "type": "boolean",
              "default": true
            },
            "outline": {
              "description": "Return the file's symbol outline (as `code_outline` renders it)\ninstead of its text; needs the codeindex plugin. Not combinable with\nany other option.",
              "type": "boolean",
              "default": false
            }
          },
          "required": [
            "path"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "remind_me_in",
        "description": "Set a timer instead of sleeping: returns at once; when it fires, `message` comes back to you as a `<reminder>` input and starts (or joins) a turn. Use it whenever you are waiting for a process, a deploy, a person or a job — end your turn after setting it. Limits: 5 s to 24 h, 8 pending per session.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "RemindMeInArgs",
          "description": "Arguments for [`RemindMeInTool`].",
          "type": "object",
          "properties": {
            "seconds": {
              "description": "Delay in seconds, 5 to 86400.",
              "type": "integer",
              "format": "uint64",
              "minimum": 0
            },
            "message": {
              "description": "What to tell yourself when it fires (≤ 2000 chars).",
              "type": "string"
            }
          },
          "required": [
            "seconds",
            "message"
          ]
        },
        "strict": false
      }
    },
    {
      "type": "function",
      "function": {
        "name": "screen",
        "description": "The current screen of a PTY job (120×40, blank rows dropped, cursor on the last line). For line output the log file under `read_file` is the full history.",
        "parameters": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "ScreenArgs",
          "description": "Arguments for [`ScreenTool`].",
          "type": "object",
          "properties": {
            "id": {
              "description": "`j4` or the job's `name`.",
